{
  "findings": [
    {
      "ref": "[D528]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with children on Roblox.",
      "stance": "risk",
      "quote": "Researchers using under-13 accounts reported encountering sexual references and offensive language within minutes of entering certain games."
    },
    {
      "ref": "[D528]",
      "area": "contact",
      "claim": "A parent reports that voice chat systems could expose children to inappropriate content and contact from adults.",
      "stance": "risk",
      "quote": "In one shocking incident, a test account created by NCOSE researchers in October and registered to a 5-year-old was “immediately” granted access to “dating, romance and … voice chat experiences where the user could be connected to strangers online.”"
    },
    {
      "ref": "[D529]",
      "area": "contact",
      "claim": "A parent reports that text and voice chat features facilitate predation and abuse by enabling adult contact with minors.",
      "stance": "risk",
      "quote": "Fairplay and the National Center for Online Sexual Exploitation (NCOSE) said Wednesday that Roblox’s voice and text chat features “are a source of substantial harm to children, facilitating predation and abuse by enabling adult contact with minors.”"
    },
    {
      "ref": "[D528]",
      "area": "money",
      "claim": "A parent reports that the platform uses a complex virtual currency system that makes it hard for children to understand real-world costs and can lead to large unexpected spending.",
      "stance": "risk",
      "quote": "According to the filing, it was \"nearly impossible\" to track the real-world cost of virtual items."
    },
    {
      "ref": "[D528]",
      "area": "money",
      "claim": "A parent reports that children can spend thousands of dollars on in-game purchases without effective limits.",
      "stance": "risk",
      "quote": "A parent said their 10-year-old daughter spent more than $7,000 (£5,200) in two months despite attempts to limit purchases."
    },
    {
      "ref": "[D528]",
      "area": "money",
      "claim": "A parent reports that loot boxes and chance-based rewards are used to encourage spending.",
      "stance": "risk",
      "quote": "Some experiences also use what the complaint described as \"gambling-like\" mechanics, such as loot boxes or chance-based rewards, which campaigners argue children may not fully understand."
    },
    {
      "ref": "[D528]",
      "area": "money",
      "claim": "A parent reports that the platform uses engagement‑maximising design features to pressure children into spending money.",
      "stance": "risk",
      "quote": "The filing also alleged \"engagement‑maximising\" design features were used to keep children on Roblox."
    },
    {
      "ref": "[D528]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data and may share it with third parties for advertising.",
      "stance": "risk",
      "quote": "The filing also alleged that Roblox uses a \"complex virtual currency system\" called Robux that manipulates kids into spending huge sums of their parents’ money without their knowledge."
    },
    {
      "ref": "[D528]",
      "area": "data",
      "claim": "A parent reports that the platform can track user behaviour and use it for targeted advertising.",
      "stance": "risk",
      "quote": "The filing also alleged that Roblox uses addictive and gambling‑like design features to get kids hooked."
    },
    {
      "ref": "[D528]",
      "area": "age_gating",
      "claim": "A parent reports that age‑gating features are easy for children to bypass.",
      "stance": "risk",
      "quote": "Drew Benvie, chief executive of social media consultancy Battenhall and founder of the youth safety nonprofit Raise, said creating age limits for features will only go so far to keeping children safe on Roblox."
    },
    {
      "ref": "[D528]",
      "area": "age_gating",
      "claim": "A parent reports that age‑based accounts and parental controls are insufficient and can be circumvented.",
      "stance": "risk",
      "quote": "Fairplay and NCOSE allege that it still easy to bypass restrictions – in part because ones set up by Roblox do not apply to chat tools built by third‑party developers that are active on the platform."
    },
    {
      "ref": "[D528]",
      "area": "content",
      "claim": "A parent reports that children encounter sexual references, offensive language, and grooming within minutes of joining certain games.",
      "stance": "risk",
      "quote": "Researchers using under‑13 accounts reported encountering sexual references and offensive language within minutes of entering an experience called ‘ChatSim,’ which explicitly advertises in its thumbnail that players can ‘chat without restrictions.’"
    },
    {
      "ref": "[D529]",
      "area": "content",
      "claim": "A parent reports that children have been targeted by predators who used Roblox to groom and exploit them.",
      "stance": "risk",
      "quote": "The cases include a wrongful death lawsuit filed in September 2025 by the mother of an autistic teenager who died by suicide after falling victim to a “sextortion” plot by someone who made contact with him on Roblox."
    },
    {
      "ref": "[D528]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced lawsuits and regulatory scrutiny over child safety and spending practices.",
      "stance": "risk",
      "quote": "More than 140 pending lawsuits in federal courts around the country accuse the company of facilitating child sexual exploitation, according to Reuters."
    }
  ]
}
